fs.writeFileSync(path.join(root,'actual-tier0-admission.json'),JSON.stringify({classification:'ACTUAL_TIER0_HTTP_HANDLER_INTERCEPTED_QUEUE_NO_INFERENCE',status:'PASS',acceptedStatus:result.statusCode,forgedPinStatus:rejected.statusCode,inputHash:record.inputHash,expectedInputHash:hashChatInput(user.workspaceId+':'+user.id+':'+input.sessionId,JSON.stringify(expectedInput)),scope:'Actual HTTP authentication, server resolution and exact queue input bytes/hash through injected queue adapter; no Redis durability or model answer claim.'},null,2));await examination.close();dropChatRequestMemoryCacheForTests();configureChatRequestStore(null);
await app.listen({host:'127.0.0.1',port:3148});fs.writeFileSync(readyFile,JSON.stringify({tokens,candidateIds,sourceEvidenceId:source.id,sourceFactsDigest:source.digest,clock:'2026-10-10T18:40:00Z',clockClassification:'HISTORICAL_REPLAY_NOT_CURRENT_SOURCE_FRESHNESS',classification:'REAL_RETAINED_OBSERVATIONS_ISOLATED_AUTH_AND_ENRICHMENT_FIXTURE'}));

"use client";

import { hasReasoningFailure, isConfirmedReasoning } from "@/lib/pillow/confirmed-reasoning";

import { subscribeRead } from "@/lib/cockpit/subscribe-read";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { usePathname } from "next/navigation";
import { brainDispatch } from "@/lib/brain/client";
import type {
  GlobalAssistantAction,
  GlobalAssistantContext,
  GlobalAssistantResponse,
  GlobalAssistantTarget,
} from "@/lib/cockpit/global-assistant/types";
import {
  appendPillowTurn,
  loadPillowPanelPreferences,
  loadPillowSession,
  preservePillowLocalArchive,
  savePillowPanelPreferences,
  savePillowSession,
  type PillowConversationTurn,
  type PillowSessionSnapshot,
} from "@/lib/cockpit/pillow/pillow-session-store";
import {readTwinChatContext,setTwinChatContext,twinContextEvent} from '@/lib/owner/twin-chat-context';
import { createPillowHostSession, fetchPillowHistory, retrievePillowChat, sendPillowChat } from "@/lib/pillow/client";
import { reconcilePillowHistory, serverPillowHistory } from "@/lib/pillow/reconcile-history";
import { clearPendingPillowReceipt, loadPendingPillowReceipts, savePendingPillowReceipt } from "@/lib/pillow/pending-receipts";
import { mapPillowChatToAssistantResponse } from "@/lib/pillow/map-response";
import type { PillowChatArtifact, PillowChatResult } from "@/lib/pillow/types";
import {
  EXECUTIVE_TERMINAL_INFRASTRUCTURE_REPLY,
  EXECUTIVE_RECOVERING_LABEL,
  EXECUTIVE_STARTING_LABEL,
  readinessLabel as formatReadinessLabel,
  toExecutiveChatMessage,
  toExecutiveSurfaceMessage,
  type ExecutiveReadinessPhase,
} from "@/lib/pillow/executive-surface";
import {
  buildExecutiveContextSnapshot,
  buildPillowActionPrompt,
  buildPillowWorkspaceContext,
  buildProactiveGuidance,
  resolveCockpitScreenContext,
  type PillowExecutiveContextSnapshot,
  type PillowGuidanceItem,
  type PillowPageContextOverride,
  type PillowWorkspaceContext,
} from "@/lib/pillow-ux";
import { useFounderShellOptional } from "@/lib/founder-shell/FounderShellProvider";
import { useAuth } from "@/lib/auth/context";
import {readProductContext,referenceIdentity,selectProduct,type AttachedProduct,type ProductReference} from "@/lib/pillow/product-context";

type GlobalAiAssistantState = {
  expanded: boolean;
  panelWidthPx: number;
  voiceEnabled: boolean;
  loading: boolean;
  context: GlobalAssistantContext | null;
  lastResponse: GlobalAssistantResponse | null;
  activeTarget: GlobalAssistantTarget | null;
  queryDraft: string;
  conversation: PillowConversationTurn[];
  hostSessionId: string | null;
  pillowConnected: boolean;
  /** True only when Pillow session is ready for Grand King conversation. */
  executiveReady: boolean;
  readinessPhase: ExecutiveReadinessPhase;
  readinessLabel: string;
  connectionError: string | null;
  pageOverride: PillowPageContextOverride | null;
  executiveSnapshot: PillowExecutiveContextSnapshot | null;
  proactiveGuidance: PillowGuidanceItem[];
  workspaceContext: PillowWorkspaceContext | null;
};

type GlobalAiAssistantContextValue = GlobalAiAssistantState & {
  attachedProducts: AttachedProduct[];
  attachProduct: (reference:ProductReference,compare?:boolean)=>Promise<void>;
  removeProduct: (missionId:string)=>void;
  expand: () => void;
  collapse: () => void;
  toggle: () => void;
  ensureHostSession: () => Promise<string | null>;
  setQueryDraft: (query: string) => void;
  setPanelWidthPx: (widthPx: number) => void;
  setVoiceEnabled: (enabled: boolean) => void;
  setPageOverride: (override: PillowPageContextOverride | null) => void;
  refreshContext: () => Promise<void>;
  runAction: (
    action: GlobalAssistantAction,
    target?: GlobalAssistantTarget,
    query?: string,
  ) => Promise<void>;
  ask: (query: string, target?: GlobalAssistantTarget) => Promise<void>;
  explain: (label: string, targetId?: string, value?: string) => void;
  recommend: () => void;
  summarise: () => void;
  nextAction: () => void;
};

const GlobalAiAssistantContext = createContext<GlobalAiAssistantContextValue | null>(null);
const UNCONFIRMED_REQUEST_MESSAGE = "Pillow is unavailable. This instruction has not been confirmed as accepted or completed. No automatic repeat was attempted.";

export function GlobalAiAssistantProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  // Remount on identity change: never render the previous owner's transcript,
  // context, active request or session for even one frame of the next account.
  return <GlobalAiAssistantSession key={user ? `${user.id}:${user.workspaceId}` : "anonymous"}>{children}</GlobalAiAssistantSession>;
}

function GlobalAiAssistantSession({ children }: { children: ReactNode }) {
  const pathname = usePathname();
  const { user } = useAuth();
  const founderShell = useFounderShellOptional();
  const panelPrefs = loadPillowPanelPreferences();
  const savedSession = loadPillowSession(user?.id);
  const recoveryLoopActive = useRef(false);
  const chatSubmissionActive = useRef(false);
  const activeOwnerId = useRef(user?.id);
  const navHistoryRef = useRef<string[]>([pathname]);

  const [state, setState] = useState<GlobalAiAssistantState>({
    expanded: panelPrefs.expanded,
    panelWidthPx: panelPrefs.widthPx,
    voiceEnabled: panelPrefs.voiceEnabled,
    loading: false,
    context: null,
    lastResponse: null,
    activeTarget: null,
    queryDraft: "",
    conversation: savedSession?.turns ?? [],
    hostSessionId: savedSession?.hostSessionId ?? null,
    pillowConnected: false,
    executiveReady: false,
    readinessPhase: "starting",
    readinessLabel: EXECUTIVE_STARTING_LABEL,
    connectionError: null,
    pageOverride: null,
    executiveSnapshot: null,
    proactiveGuidance: [],
    workspaceContext: null,
  });

  useEffect(() => {
    activeOwnerId.current = user?.id;
    return () => { activeOwnerId.current = undefined; };
  }, [user?.id]);

  const markReady = useCallback((hostSessionId: string, conversation?: PillowConversationTurn[]) => {
    setState((s) => ({
      ...s,
      hostSessionId,
      pillowConnected: true,
      executiveReady: true,
      readinessPhase: "ready",
      readinessLabel: formatReadinessLabel("ready"),
      connectionError: null,
      ...(conversation ? { conversation } : {}),
    }));
  }, []);

  const markStarting = useCallback((phase: ExecutiveReadinessPhase = "starting", error?: string | null) => {
    const surface = error ? toExecutiveSurfaceMessage(error) : formatReadinessLabel(phase);
    setState((s) => ({
      ...s,
      pillowConnected: false,
      executiveReady: false,
      readinessPhase: phase,
      readinessLabel: surface,
      connectionError: surface,
    }));
  }, []);

  useEffect(() => {
    const history = navHistoryRef.current;
    if (history[history.length - 1] !== pathname) {
      navHistoryRef.current = [...history, pathname].slice(-20);
    }
  }, [pathname]);

  useEffect(() => {
    savePillowPanelPreferences({
      expanded: state.expanded,
      widthPx: state.panelWidthPx,
      voiceEnabled: state.voiceEnabled,
    });
  }, [state.expanded, state.panelWidthPx, state.voiceEnabled]);

  const buildWorkspaceContext = useCallback(
    (
      brainContext: GlobalAssistantContext | null,
      pageOverride: PillowPageContextOverride | null,
    ): PillowWorkspaceContext => {
      const snapshot = buildExecutiveContextSnapshot({
        founderShell: founderShell?.data ?? null,
        brainContext,
        // Never treat mission count as approvals — that caused Home vs Pillow Context contradictions.
        pendingApprovals: brainContext?.executiveContext?.pendingApprovals ?? 0,
        nextExecutiveAction: brainContext?.executiveContext?.nextExecutiveAction ?? null,
      });

      return buildPillowWorkspaceContext({
        screenPath: pathname,
        navigationHistory: navHistoryRef.current,
        pageOverride,
        executive: {
          currentBusiness: snapshot.currentBusiness,
          currentMission: snapshot.currentMission,
          currentJourney: snapshot.currentJourney,
          currentRoadmapItem: snapshot.currentRoadmapItem,
          builderStatus: snapshot.builderStatus,
          supervisorStatus: snapshot.supervisorStatus,
          productionStatus: snapshot.productionStatus,
          guardianStatus: snapshot.guardianStatus,
          pendingApprovals: snapshot.pendingApprovals,
          unreadNotifications: snapshot.alertCount,
          recommendations: snapshot.recommendations,
          risks: snapshot.risks,
        },
      });
    },
    [founderShell?.data, pathname],
  );

  const syncExecutiveAwareness = useCallback(
    (brainContext: GlobalAssistantContext | null, pageOverride: PillowPageContextOverride | null) => {
      const snapshot = buildExecutiveContextSnapshot({
        founderShell: founderShell?.data ?? null,
        brainContext,
        pendingApprovals: brainContext?.executiveContext?.pendingApprovals ?? 0,
        nextExecutiveAction: brainContext?.executiveContext?.nextExecutiveAction ?? null,
      });
      const guidance = buildProactiveGuidance(snapshot);
      const workspaceContext = buildWorkspaceContext(brainContext, pageOverride);
      setState((s) => ({
        ...s,
        executiveSnapshot: snapshot,
        proactiveGuidance: guidance,
        workspaceContext,
      }));
    },
    [buildWorkspaceContext, founderShell?.data],
  );

  const historyOwnerId = user?.id;
  const historyWorkspaceId = user?.workspaceId;
  useEffect(() => {
    if (!historyOwnerId) return;
    let cancelled = false;
    let running = false;
    const hydrate = async () => {
      if (running || chatSubmissionActive.current || recoveryLoopActive.current) return;
      running = true;
      try {
        // Every device resolves the server conversation. Local storage is only a cache.
        const cached=loadPillowSession(historyOwnerId);
        const historicalBrowserTurns=(cached?.turns ?? []).filter(turn=>!turn.source && Number.isFinite(Date.parse(turn.recordedAt))).map(turn=>({role:turn.role==='grand-king'?'user' as const:'assistant' as const,content:turn.content,timestamp:new Date(turn.recordedAt).toISOString(),requestId:turn.requestId}));
        const session = await createPillowHostSession(historyWorkspaceId, historyOwnerId, historicalBrowserTurns);

        const history = await fetchPillowHistory(session.sessionId);
        if (cancelled || activeOwnerId.current !== historyOwnerId || chatSubmissionActive.current) return;
        const serverTurns = serverPillowHistory(history.session.conversationHistory, pathname);
        const archiveTurns: PillowConversationTurn[] = history.historicalArchive.map(turn => ({
          id:`archive-${turn.id}`, role:turn.role === 'user' ? 'grand-king' : 'pillow',
          content:turn.content, recordedAt:turn.timestamp, requestId:turn.requestId,
          screenPath:pathname, source:'historical_browser_cache',
        }));
        const turns = reconcilePillowHistory(serverTurns, archiveTurns);
        const previous = loadPillowSession(historyOwnerId);
        // Preserve browser-only historical records separately; never silently
        // upload them as server evidence or inference context.
        preservePillowLocalArchive(previous, turns, historyOwnerId);
        savePillowSession({turns, lastScreenPath: pathname, updatedAt: new Date().toISOString(), hostSessionId: session.sessionId}, historyOwnerId);
        markReady(session.sessionId, turns);
      } catch {
        if (!cancelled && activeOwnerId.current === historyOwnerId) {
          markStarting("recovering", "Server conversation history could not be synchronized. Any displayed cached history is device-local and unverified.");
        }
      } finally { running = false; }
    };
    void hydrate();
    const refresh = () => { if (document.visibilityState === "visible") void hydrate(); };
    window.addEventListener("focus", refresh);
    window.addEventListener("online", refresh);
    document.addEventListener("visibilitychange", refresh);
    return () => {
      cancelled = true;
      window.removeEventListener("focus", refresh);
      window.removeEventListener("online", refresh);
      document.removeEventListener("visibilitychange", refresh);
    };
  }, [markReady, markStarting, pathname, historyOwnerId, historyWorkspaceId]);

  const refreshContext = useCallback(async () => {
    // Never share chat `loading` with background context refresh — that disabled Send
    // and showed "Preparing your executive response…" while Brain context was fetching.
    try {
      const result = await brainDispatch<GlobalAssistantContext>({
        module: "cockpit-global-assistant",
        action: "context",
        payload: { screenPath: pathname },
      });
      const brainContext = result.result ?? null;
      setState((s) => ({
        ...s,
        context: brainContext,
      }));
      syncExecutiveAwareness(brainContext, state.pageOverride);
    } catch {
      // Background awareness only — do not block the composer.
    }
  }, [pathname, state.pageOverride, syncExecutiveAwareness]);

  useEffect(() => subscribeRead(refreshContext), [refreshContext]);

  useEffect(() => {
    if (state.context) {
      return subscribeRead(() => syncExecutiveAwareness(state.context, state.pageOverride));
    }
  }, [founderShell?.data, state.context, state.pageOverride, syncExecutiveAwareness]);

  const appendUserTurnNow = useCallback(
    (query: string) => {
      if (!user || activeOwnerId.current !== user.id) return;
      const session = appendPillowTurn(loadPillowSession(user.id), {
        role: "grand-king",
        content: query,
        screenPath: pathname,
      }, user.id);
      setState((s) => ({
        ...s,
        conversation: session.turns,
        hostSessionId: session.hostSessionId ?? s.hostSessionId,
      }));
    },
    [pathname, user],
  );

  const appendPillowTurnOnly = useCallback(
    (response: GlobalAssistantResponse, artifacts?: PillowChatArtifact[], requestId?: string, isStatus = false) => {
      if (!user || activeOwnerId.current !== user.id) return;
      const session = appendPillowTurn(loadPillowSession(user.id), {
        role: "pillow",
        requestId,
        content: isStatus ? response.interactionSummary : toExecutiveChatMessage(
          response.interactionSummary,
          EXECUTIVE_TERMINAL_INFRASTRUCTURE_REPLY,
        ),
        screenPath: pathname,
        artifacts,
      }, user.id);
      setState((s) => ({
        ...s,
        conversation: session.turns,
        hostSessionId: session.hostSessionId ?? s.hostSessionId,
        lastResponse: response,
      }));
    },
    [pathname, user],
  );

  /** Legacy helper — user+response. Prefer appendUserTurnNow + appendPillowTurnOnly. */
  const recordConversation = useCallback(
    (
      query: string,
      response: GlobalAssistantResponse | null,
      artifacts?: PillowChatArtifact[],
    ) => {
      appendUserTurnNow(query);
      if (response) appendPillowTurnOnly(response, artifacts);
    },
    [appendPillowTurnOnly, appendUserTurnNow],
  );

  const ensureHostSession = useCallback(async (): Promise<string | null> => {
    if (!user || activeOwnerId.current !== user.id) return null;
    try {
      const session = await createPillowHostSession(user.workspaceId, user.id);
      if (activeOwnerId.current !== user.id) return null;
      const snapshot: PillowSessionSnapshot = {
        turns: loadPillowSession(user.id)?.turns ?? [],
        lastScreenPath: pathname,
        updatedAt: new Date().toISOString(),
        hostSessionId: session.sessionId,
      };
      savePillowSession(snapshot, user.id);
      markReady(session.sessionId);
      return session.sessionId;
    } catch (error) {
      if (activeOwnerId.current !== user.id) return null;
      markStarting(
        "recovering",
        error instanceof Error ? error.message : EXECUTIVE_RECOVERING_LABEL,
      );
      return null;
    }
  }, [markReady, markStarting, pathname, user]);

  const presentChatResult = useCallback((chatResult: PillowChatResult, query: string, target?: GlobalAssistantTarget) => {
    if (!user || activeOwnerId.current !== user.id) return;
    // Restore/reopen follows the same rebound-session contract as the first send.
    if (chatResult.reboundSessionId) {
      const existing = loadPillowSession(user.id);
      if (existing?.hostSessionId !== chatResult.reboundSessionId) {
        savePillowSession({
          turns: existing?.turns ?? [],
          lastScreenPath: existing?.lastScreenPath ?? pathname,
          updatedAt: new Date().toISOString(),
          hostSessionId: chatResult.reboundSessionId,
        }, user.id);
        markReady(chatResult.reboundSessionId, existing?.turns ?? []);
      }
    }
    const response = mapPillowChatToAssistantResponse(chatResult, query);
    const isStatus = hasReasoningFailure(chatResult) || chatResult.kind === "durable_pending" ||
      chatResult.status === "FAILED_FATAL" || chatResult.status === "FAILED" ||
      chatResult.status === "RESULT_UNAVAILABLE";
    const preserveReasoning = isConfirmedReasoning(chatResult);
    const surfaced = isStatus || preserveReasoning ? response : {
      ...response,
      interactionSummary: toExecutiveChatMessage(response.interactionSummary, EXECUTIVE_TERMINAL_INFRASTRUCTURE_REPLY),
      reason: toExecutiveChatMessage(response.reason, EXECUTIVE_TERMINAL_INFRASTRUCTURE_REPLY),
      recommendedNextAction: toExecutiveChatMessage(response.recommendedNextAction, EXECUTIVE_TERMINAL_INFRASTRUCTURE_REPLY),
    };
    appendPillowTurnOnly(surfaced, chatResult.artifacts, chatResult.requestId, isStatus || preserveReasoning);
    if (user && chatResult.kind !== "durable_pending" && chatResult.status !== "RESULT_UNAVAILABLE") {
      clearPendingPillowReceipt(user.id, chatResult.requestId);
    }
    setState((s) => ({
      ...s,
      lastResponse: surfaced,
      connectionError: isStatus ? chatResult.message : null,
      activeTarget: target ?? null,
    }));
  }, [appendPillowTurnOnly, markReady, pathname, user]);

  useEffect(() => {
    if (!user) return;
    const controller = new AbortController();
    // Refresh/remount resumes GET on confirmed IDs, never the original POST.
    const receipts = loadPendingPillowReceipts(user.id);
    void (async () => {
      for (const receipt of receipts) {
        if (controller.signal.aborted) break;
        try {
          const result = await retrievePillowChat(receipt, { signal: controller.signal });
          if (!controller.signal.aborted) presentChatResult(result, receipt.query);
        } catch {
          // Unmount/sign-out cancels retrieval; the owner-scoped receipt remains saved.
        }
      }
    })();
    return () => controller.abort();
  }, [user, presentChatResult]);

  // Slow recovery only after the initial bootstrap exhausted — never parallel with it.
  useEffect(() => {
    if (!user || state.executiveReady || state.readinessPhase !== "delayed") return;
    if (recoveryLoopActive.current) return;
    recoveryLoopActive.current = true;
    let cancelled = false;

    void (async () => {
      // Single bounded recovery attempt — multi-retry loops stampeded Brain (503 + lag).
      for (let attempt = 1; attempt <= 1 && !cancelled; attempt += 1) {
        const id = await ensureHostSession();
        if (id || cancelled) break;
        markStarting("delayed");
        await new Promise((r) => setTimeout(r, 15_000));
      }
      recoveryLoopActive.current = false;
    })();

    return () => {
      cancelled = true;
      recoveryLoopActive.current = false;
    };
  }, [user, state.executiveReady, state.readinessPhase, ensureHostSession, markStarting]);

  const [attachedProducts,setAttachedProducts]=useState<AttachedProduct[]>([]);
  const productSelectionVersion=useRef(0);
  const attachedProductsRef=useRef<AttachedProduct[]>([]);
  useEffect(()=>{
    const clearAttached=()=>{
      productSelectionVersion.current++;
      attachedProductsRef.current=[];
      setAttachedProducts([]);
    };
    clearAttached();
    window.addEventListener(twinContextEvent,clearAttached);
    return ()=>window.removeEventListener(twinContextEvent,clearAttached);
  },[user?.id,user?.workspaceId]);
  const attachProduct=useCallback(async(reference:ProductReference,compare=false)=>{
    if(state.loading)throw Error("Wait for the current message before changing product context.");
    const version=++productSelectionVersion.current, owner=activeOwnerId.current;
    const product=await readProductContext(reference);
    if(version!==productSelectionVersion.current||owner!==activeOwnerId.current)throw Error("Product selection changed before verification completed.");
    const next=selectProduct(attachedProductsRef.current,product,compare);
    if(owner)setTwinChatContext(owner,null);
    attachedProductsRef.current=next;setAttachedProducts(next);
  },[state.loading]);
  const removeProduct=useCallback((missionId:string)=>{
    if(state.loading)return;
    productSelectionVersion.current++;
    const next=attachedProductsRef.current.filter(p=>referenceIdentity(p.reference)!==missionId);
    attachedProductsRef.current=next;setAttachedProducts(next);
  },[state.loading]);

  const sendViaPillow = useCallback(
    async (
      query: string,
      target?: GlobalAssistantTarget,
    ): Promise<boolean> => {
      const productContext=user?readTwinChatContext(user.id):null;
      const contextKey=productContext?JSON.stringify(productContext):undefined;
      productSelectionVersion.current++;
      const buildContextWithContinuity = (): Record<string, unknown> => {
        const base = buildWorkspaceContext(state.context, state.pageOverride);
        const turns = (loadPillowSession(user?.id)?.turns ?? [])
          .filter(t => t.source === "server_persisted_transcript")
          .slice(-12)
          .map((t) => ({
            role: t.role,
            content:
              String(t.content ?? "").length > 8000
                ? `${String(t.content).slice(0, 7970)}…`
                : t.content,
          }));
        return {
          ...base,
          recentConversationTurns: turns,
          ...(attachedProducts.length?{productContext:attachedProducts.length===1?attachedProducts[0].reference:attachedProducts.map(p=>p.reference)}:(productContext?{productContext}:{})),
        };
      };

      const productContextKey=JSON.stringify({workspace:user?.workspaceId,refs:attachedProducts.map(p=>p.reference)});
      const attemptChat = async (sessionId: string): Promise<boolean> => {
        const priorReceipt = user
          ? loadPendingPillowReceipts(user.id).find((row) => row.query === query && row.contextKey === contextKey)
          : undefined;
        if(priorReceipt && (priorReceipt.productContextKey===undefined?attachedProducts.length>0:priorReceipt.productContextKey!==productContextKey))throw Error("An earlier request with this message is still pending under different product context. Inspect that saved request before sending again.");
        const chatResult: PillowChatResult & { reboundSessionId?: string } = priorReceipt
          ? await retrievePillowChat(priorReceipt)
          : await sendPillowChat({
            message: query,
            sessionId,
            workspaceContext: buildContextWithContinuity(),
          }, {
            onAccepted: (receipt) => {
              if (user) savePendingPillowReceipt(user.id, { ...receipt, query, contextKey, productContextKey });
            },
          });
        if (!user || activeOwnerId.current !== user.id) return true;
        presentChatResult(chatResult, query, target);
        setState((s) => ({
          ...s,
          loading: false,
          pillowConnected: true,
          executiveReady: true,
          readinessPhase: "ready",
          readinessLabel: formatReadinessLabel("ready"),
          activeTarget: target ?? null,
        }));
        return true;
      };

      const sessionId = await ensureHostSession();
      if (!sessionId) return false;

      try {
        return await attemptChat(sessionId);
      } catch (error) {
        if (!user || activeOwnerId.current !== user.id) return true;
        // A timeout/401/404 is not proof that the original POST was rejected.
        // Preserve continuity and never execute the instruction a second time.
        const message = error instanceof Error ? error.message : "The request status could not be confirmed. No automatic repeat was attempted.";
        markStarting("delayed", message);
        appendPillowTurnOnly({
          ...mapPillowChatToAssistantResponse({
            requestId: "", sessionId, message, kind: "error", latencyMs: 0,
          }, query),
          interactionSummary: message,
        }, undefined, undefined, true);
        return true;
      }
    },
    [
      appendPillowTurnOnly,
      buildWorkspaceContext,
      ensureHostSession,
      markStarting,
      presentChatResult,
      attachedProducts,
      state.context,
      state.pageOverride,
      user,
    ],
  );

  const askPillow = useCallback(
    async (query: string, target?: GlobalAssistantTarget) => {
      const trimmed = query.trim();
      if (!trimmed || chatSubmissionActive.current) return;
      chatSubmissionActive.current = true;

      // Render Grand King message immediately; show honest processing state while Pillow works.
      appendUserTurnNow(trimmed);
      setState((s) => ({
        ...s,
        expanded: true,
        loading: true,
        activeTarget: target ?? null,
        queryDraft: "",
      }));

      try {
        if (!state.executiveReady) {
          void ensureHostSession();
        }

        const sent = await sendViaPillow(trimmed, target);
        if (sent) return;

        // Honest terminal — not a completed executive answer; no recovery residue.
        appendPillowTurnOnly({
          action: "ask",
          currentContext: "Executive infrastructure",
          reason: UNCONFIRMED_REQUEST_MESSAGE,
          supportingEvidence: [],
          recommendedNextAction: "Restore the connection and check request status before sending this instruction again.",
          confidence: "unavailable",
          suggestedFollowUps: [],
          interactionIntent: "general",
          interactionSummary: UNCONFIRMED_REQUEST_MESSAGE,
          computedAt: new Date().toISOString(),
          futureCapabilities: [],
        });
        setState((s) => ({
          ...s,
          connectionError: s.connectionError ?? EXECUTIVE_RECOVERING_LABEL,
        }));
      } finally {
        chatSubmissionActive.current = false;
        setState((s) => (s.loading ? { ...s, loading: false } : s));
      }
    },
    [
      appendPillowTurnOnly,
      appendUserTurnNow,
      ensureHostSession,
      sendViaPillow,
      state.executiveReady,
    ],
  );

  const runAction = useCallback(
    async (
      action: GlobalAssistantAction,
      target?: GlobalAssistantTarget,
      query?: string,
    ) => {
      const screen = resolveCockpitScreenContext(pathname);
      const userQuery =
        query ??
        (action === "ask"
          ? (target?.label ?? "")
          : buildPillowActionPrompt(action, {
              screenTitle: screen.screenTitle,
              screenPath: pathname,
              targetLabel: target?.label,
              nextExecutiveAction: state.executiveSnapshot?.nextExecutiveAction,
            }));

      if (action === "ask") {
        await askPillow(userQuery, target);
        return;
      }
      if (chatSubmissionActive.current) return;
      chatSubmissionActive.current = true;

      setState((s) => ({
        ...s,
        expanded: true,
        loading: true,
        activeTarget: target ?? null,
      }));

      try {
        const sent = await sendViaPillow(userQuery, target);
        if (sent) return;

        recordConversation(userQuery, {
          action,
          currentContext: "Executive infrastructure",
          reason: UNCONFIRMED_REQUEST_MESSAGE,
          supportingEvidence: [],
          recommendedNextAction:
            "Restore the connection and check request status before sending this instruction again.",
          confidence: "unavailable",
          suggestedFollowUps: [],
          interactionIntent: "general",
          interactionSummary: UNCONFIRMED_REQUEST_MESSAGE,
          computedAt: new Date().toISOString(),
          futureCapabilities: [],
        });
        setState((s) => ({
          ...s,
          lastResponse: {
            action,
            currentContext: "Executive infrastructure",
            reason: UNCONFIRMED_REQUEST_MESSAGE,
            supportingEvidence: [],
            recommendedNextAction:
              "Restore the connection and check request status before sending this instruction again.",
            confidence: "unavailable",
            suggestedFollowUps: [],
            interactionIntent: "general",
            interactionSummary: UNCONFIRMED_REQUEST_MESSAGE,
            computedAt: new Date().toISOString(),
            futureCapabilities: [],
          },
          connectionError: s.readinessLabel || EXECUTIVE_RECOVERING_LABEL,
        }));
      } finally {
        chatSubmissionActive.current = false;
        setState((s) => (s.loading ? { ...s, loading: false } : s));
      }
    },
    [
      askPillow,
      pathname,
      recordConversation,
      sendViaPillow,
      state.executiveSnapshot?.nextExecutiveAction,
    ],
  );

  const ask = useCallback(
    (query: string, target?: GlobalAssistantTarget) => runAction("ask", target, query),
    [runAction],
  );

  const explain = useCallback(
    (label: string, targetId?: string, value?: string) =>
      void runAction("explain", { targetType: "panel", targetId, label, value }),
    [runAction],
  );

  const recommend = useCallback(() => void runAction("recommend"), [runAction]);
  const summarise = useCallback(() => void runAction("summarise"), [runAction]);
  const nextAction = useCallback(() => void runAction("next_action"), [runAction]);

  const setPageOverride = useCallback((override: PillowPageContextOverride | null) => {
    setState((s) => ({ ...s, pageOverride: override }));
  }, []);

  const value = useMemo(
    () => ({
      ...state,
      attachedProducts,attachProduct,removeProduct,
      expand: () => {
        // Mark panel expanded only. Do NOT auto-dispatch the Pillow focus event —
        // Executive Home mounts expand() and that was yanking page scroll into Pillow.
        // Explicit openers (Ask AI / Ask Pillow) dispatch the focus event themselves.
        setState((s) => s.expanded ? s : ({ ...s, expanded: true }));
      },
      collapse: () => setState((s) => ({ ...s, expanded: false })),
      toggle: () => setState((s) => ({ ...s, expanded: !s.expanded })),
      ensureHostSession,
      setQueryDraft: (queryDraft: string) => setState((s) => ({ ...s, queryDraft })),
      setPanelWidthPx: (panelWidthPx: number) =>
        setState((s) => ({
          ...s,
          panelWidthPx: Math.max(360, Math.min(960, panelWidthPx)),
        })),
      setVoiceEnabled: (voiceEnabled: boolean) => setState((s) => ({ ...s, voiceEnabled })),
      setPageOverride,
      refreshContext,
      runAction,
      ask,
      explain,
      recommend,
      summarise,
      nextAction,
    }),
    [
      state,
      attachedProducts,attachProduct,removeProduct,
      ensureHostSession,
      setPageOverride,
      refreshContext,
      runAction,
      ask,
      explain,
      recommend,
      summarise,
      nextAction,
    ],
  );

  return (
    <GlobalAiAssistantContext.Provider value={value}>
      {children}
    </GlobalAiAssistantContext.Provider>
  );
}

export function useGlobalAiAssistant() {
  const ctx = useContext(GlobalAiAssistantContext);
  if (!ctx) {
    throw new Error("useGlobalAiAssistant must be used within GlobalAiAssistantProvider");
  }
  return ctx;
}

export function usePillowPageContext() {
  const ctx = useContext(GlobalAiAssistantContext);
  return {
    setPageOverride: ctx?.setPageOverride ?? (() => undefined),
    pageOverride: ctx?.pageOverride ?? null,
  };
}

/**
 * Pillow operating shell — conversation persistence (frontend only, no secrets).
 */

export const PILLOW_SESSION_STORAGE_KEY = "empireai:pillow:session:v1" as const;
export const PILLOW_PANEL_STATE_KEY = "empireai:pillow:panel:v1" as const;

export type PillowConversationTurn = {
  id: string;
  role: "grand-king" | "pillow";
  content: string;
  screenPath: string;
  recordedAt: string;
  requestId?: string;
  productContext?: Record<string, unknown>;
  source?: "server_persisted_transcript" | "historical_browser_cache";
  artifacts?: import("@/lib/pillow/types").PillowChatArtifact[];
};

export type PillowSessionSnapshot = {
  turns: PillowConversationTurn[];
  lastScreenPath: string;
  updatedAt: string;
  /** Host session id from /api/pillow/session — enables server-side conversation memory */
  hostSessionId?: string;
};

/** Pillow Operating Shell viewing modes (UI-only). */
export type PillowViewMode = "dock" | "float" | "workspace";

export type PillowFloatGeometry = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type PillowPanelPreferences = {
  expanded: boolean;
  widthPx: number;
  voiceEnabled: boolean;
  /**
   * @deprecated Prefer `viewMode`. Kept for backward compatibility —
   * `true` maps to `workspace` when `viewMode` is absent.
   */
  workspaceMode?: boolean;
  /** Canonical viewing mode: docked panel, floating window, or full workspace. */
  viewMode?: PillowViewMode;
  /** Mode to restore when collapsing from workspace (dock or float). */
  previousViewMode?: Exclude<PillowViewMode, "workspace">;
  /** Floating window geometry (viewport pixels). Clamped on load. */
  float?: PillowFloatGeometry;
};

export const PILLOW_DOCK_WIDTH_MIN = 360;
export const PILLOW_DOCK_WIDTH_MAX = 960;
export const PILLOW_FLOAT_WIDTH_MIN = 360;
export const PILLOW_FLOAT_HEIGHT_MIN = 320;
export const PILLOW_FLOAT_WIDTH_DEFAULT = 520;
export const PILLOW_FLOAT_HEIGHT_DEFAULT = 640;

const DEFAULT_PANEL: PillowPanelPreferences = {
  expanded: true,
  widthPx: 560,
  voiceEnabled: false,
  workspaceMode: false,
  viewMode: "dock",
  previousViewMode: "dock",
};

export function clampPillowDockWidth(widthPx: number): number {
  return Math.max(
    PILLOW_DOCK_WIDTH_MIN,
    Math.min(PILLOW_DOCK_WIDTH_MAX, Number(widthPx) || DEFAULT_PANEL.widthPx),
  );
}

export function resolvePillowViewMode(
  prefs: Pick<PillowPanelPreferences, "viewMode" | "workspaceMode">,
): PillowViewMode {
  if (prefs.viewMode === "dock" || prefs.viewMode === "float" || prefs.viewMode === "workspace") {
    return prefs.viewMode;
  }
  return prefs.workspaceMode ? "workspace" : "dock";
}

/** Keep floating window fully visible inside the browser viewport. */
export function clampPillowFloatGeometry(
  geometry: PillowFloatGeometry,
  viewport: { width: number; height: number } = {
    width: typeof window !== "undefined" ? window.innerWidth : 1280,
    height: typeof window !== "undefined" ? window.innerHeight : 800,
  },
): PillowFloatGeometry {
  const maxWidth = Math.max(PILLOW_FLOAT_WIDTH_MIN, viewport.width - 16);
  const maxHeight = Math.max(PILLOW_FLOAT_HEIGHT_MIN, viewport.height - 16);
  const width = Math.max(
    PILLOW_FLOAT_WIDTH_MIN,
    Math.min(maxWidth, Number(geometry.width) || PILLOW_FLOAT_WIDTH_DEFAULT),
  );
  const height = Math.max(
    PILLOW_FLOAT_HEIGHT_MIN,
    Math.min(maxHeight, Number(geometry.height) || PILLOW_FLOAT_HEIGHT_DEFAULT),
  );
  const x = Math.max(0, Math.min(viewport.width - width, Number(geometry.x) || 0));
  const y = Math.max(0, Math.min(viewport.height - height, Number(geometry.y) || 0));
  return { x, y, width, height };
}

export function defaultPillowFloatGeometry(
  viewport: { width: number; height: number } = {
    width: typeof window !== "undefined" ? window.innerWidth : 1280,
    height: typeof window !== "undefined" ? window.innerHeight : 800,
  },
): PillowFloatGeometry {
  const width = Math.min(PILLOW_FLOAT_WIDTH_DEFAULT, Math.max(PILLOW_FLOAT_WIDTH_MIN, viewport.width - 48));
  const height = Math.min(
    PILLOW_FLOAT_HEIGHT_DEFAULT,
    Math.max(PILLOW_FLOAT_HEIGHT_MIN, viewport.height - 48),
  );
  return clampPillowFloatGeometry(
    {
      x: Math.max(24, viewport.width - width - 24),
      y: Math.max(24, Math.round((viewport.height - height) / 2)),
      width,
      height,
    },
    viewport,
  );
}

function ownerSessionKey(ownerId: string): string {
  return `${PILLOW_SESSION_STORAGE_KEY}:${encodeURIComponent(ownerId)}`;
}

export function loadPillowSession(ownerId?: string): PillowSessionSnapshot | null {
  // The old unscoped key cannot be attributed safely. Never import it into a
  // signed-in owner's conversation or send its transcript back as context.
  if (typeof window === "undefined" || !ownerId) return null;
  try {
    const raw = window.localStorage.getItem(ownerSessionKey(ownerId));
    if (!raw) return null;
    return JSON.parse(raw) as PillowSessionSnapshot;
  } catch {
    return null;
  }
}

export function savePillowSession(snapshot: PillowSessionSnapshot, ownerId?: string): void {
  if (typeof window === "undefined" || !ownerId) return;
  try {
    window.localStorage.setItem(ownerSessionKey(ownerId), JSON.stringify(snapshot));
  } catch {
    // Storage failure must not turn a delivered answer into another execution.
  }
}

export function clearPillowHostSession(ownerId?: string): void {
  const session = loadPillowSession(ownerId);
  if (!session) return;
  savePillowSession({ ...session, hostSessionId: undefined }, ownerId);
}

export function loadPillowPanelPreferences(): PillowPanelPreferences {
  if (typeof window === "undefined") return DEFAULT_PANEL;
  try {
    const raw = window.localStorage.getItem(PILLOW_PANEL_STATE_KEY);
    if (!raw) return DEFAULT_PANEL;
    const parsed = { ...DEFAULT_PANEL, ...(JSON.parse(raw) as Partial<PillowPanelPreferences>) };
    const viewMode = resolvePillowViewMode(parsed);
    const previousViewMode =
      parsed.previousViewMode === "float" || parsed.previousViewMode === "dock"
        ? parsed.previousViewMode
        : "dock";
    const float = parsed.float
      ? clampPillowFloatGeometry(parsed.float)
      : defaultPillowFloatGeometry();
    return {
      ...parsed,
      widthPx: clampPillowDockWidth(Number(parsed.widthPx) || DEFAULT_PANEL.widthPx),
      workspaceMode: viewMode === "workspace",
      viewMode,
      previousViewMode,
      float,
    };
  } catch {
    return DEFAULT_PANEL;
  }
}

export function savePillowPanelPreferences(prefs: PillowPanelPreferences): void {
  if (typeof window === "undefined") return;
  const viewMode = resolvePillowViewMode(prefs);
  const next: PillowPanelPreferences = {
    ...prefs,
    viewMode,
    workspaceMode: viewMode === "workspace",
    widthPx: clampPillowDockWidth(prefs.widthPx),
    float: prefs.float ? clampPillowFloatGeometry(prefs.float) : undefined,
  };
  window.localStorage.setItem(PILLOW_PANEL_STATE_KEY, JSON.stringify(next));
}

export function appendPillowTurn(
  session: PillowSessionSnapshot | null,
  turn: Omit<PillowConversationTurn, "id" | "recordedAt">,
  ownerId?: string,
): PillowSessionSnapshot {
  const base: PillowSessionSnapshot = session ?? {
    turns: [],
    lastScreenPath: turn.screenPath,
    updatedAt: new Date().toISOString(),
  };
  // Replace a status receipt with the answer to that same request, never duplicate it.
  const previousTurn = turn.role === "pillow" && turn.requestId
    ? base.turns.find((row) => row.role === "pillow" && row.requestId === turn.requestId)
    : undefined;
  const nextTurn: PillowConversationTurn = {
    ...turn,
    id: previousTurn?.id ?? `turn-${base.turns.length + 1}-${Date.now()}`,
    recordedAt: previousTurn?.recordedAt ?? new Date().toISOString(),
  };
  const next: PillowSessionSnapshot = {
    ...base,
    lastScreenPath: turn.screenPath,
    updatedAt: new Date().toISOString(),
    turns: (previousTurn
      ? base.turns.map((row) => row.id === previousTurn.id ? nextTurn : row)
      : [...base.turns, nextTurn]).slice(-200),
  };
  savePillowSession(next, ownerId);
  return next;
}

/** Keep unverified device-only history intact while replacing the active cache. */
export function preservePillowLocalArchive(previous: PillowSessionSnapshot | null, serverTurns: PillowConversationTurn[], ownerId: string): void {
  if (typeof window === "undefined" || !previous?.turns.length) return;
  const missing = previous.turns.filter(turn => !serverTurns.some(server =>
    server.role === turn.role && (turn.requestId ? server.requestId === turn.requestId : server.content === turn.content)));
  if (!missing.length) return;
  const key = `${ownerSessionKey(ownerId)}:unverified-archive`;
  const prior = JSON.parse(window.localStorage.getItem(key) ?? "[]") as PillowConversationTurn[];
  const merged = [...prior];
  for (const turn of missing) if (!merged.some(row => row.id === turn.id)) merged.push(turn);
  // If archival fails, caller must not overwrite the original active cache.
  window.localStorage.setItem(key, JSON.stringify(merged));
}

